using UnityEngine;

public class BurnDoTEffect : DoTEffect
{
	private static GameObject prefab;

	public static string burnStatusStr = "BurnStatus";

	public BurnEffect burnEffect;

	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/Effects/BurnEffect.prefab");
			}
			return prefab;
		}
	}

	public BurnDoTEffect(string newCat, int newLvl, Entity newEnt, Entity atkEnt)
		: base(newCat, burnStatusStr, newLvl, newEnt, atkEnt)
	{
		dotElement = ElementType.Fire;
	}

	public override void Init()
	{
		base.Init();
		burnEffect = Object.Instantiate(Prefab, parentEntity.transform.position, Quaternion.identity).GetComponent<BurnEffect>();
		burnEffect.entity = parentEntity;
		SoundManager.PlayAudioWithDistance("FlameLight", parentEntity.transform.position);
	}

	public override void CleanUp()
	{
		if (burnEffect != null)
		{
			burnEffect.Disable();
		}
	}
}
