public class BurstOnDotItem : DotEventItem
{
	public static string staticID = "BurstOnDotItem";

	private static float burstRadius = 3f;

	private ChaosQuickStopwatch cdStopwatch;

	public BurstOnDotItem()
	{
		ID = staticID;
		category = Category.Defense;
		activateOnApply = true;
		cdStopwatch = new ChaosQuickStopwatch(3f);
	}

	public override void OnDotApply(ElementType givenElement)
	{
		if (!(parentPlayer == null) && !cdStopwatch.IsRunning)
		{
			cdStopwatch.IsRunning = true;
			switch (givenElement)
			{
			case ElementType.Fire:
				FlameBurst.CreateBurst(parentPlayer.hurtBoxTransform.position, parentPlayer.skillCategory, ID, 1, burstRadius);
				break;
			case ElementType.Air:
				WindBurst.CreateBurst(parentPlayer.hurtBoxTransform.position, parentPlayer.skillCategory, ID, 2, burstRadius);
				break;
			case ElementType.Earth:
				EarthBurst.CreateBurst(parentPlayer.hurtBoxTransform.position, parentPlayer.skillCategory, ID, 3, burstRadius);
				break;
			case ElementType.Lightning:
				LightningBurst.CreateBurst(parentPlayer.hurtBoxTransform.position, parentPlayer.skillCategory, ID, 4, burstRadius);
				break;
			case ElementType.Water:
				IceBurst.CreateBurst(parentPlayer.hurtBoxTransform.position, parentPlayer.skillCategory, ID, 5, burstRadius);
				break;
			}
		}
	}
}
