using UnityEngine;

public class ElementalBurst : MonoBehaviour
{
	public Attack attack;

	public float scaleValue = 1f;

	public float destroyDelay = 1f;

	protected CircleCollider2D atkCollider;

	protected ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.125f);

	protected bool atkCompleted;

	public virtual void Awake()
	{
		attack = transform.Find("Attack").GetComponent<Attack>();
		atkCollider = attack.GetComponent<CircleCollider2D>();
	}

	public virtual void Start()
	{
		atkStopwatch.IsRunning = true;
		atkCollider.radius = scaleValue;
		Object.Destroy(gameObject, destroyDelay);
	}

	public virtual void FixedUpdate()
	{
		if (!atkCompleted && !atkStopwatch.IsRunning)
		{
			atkCompleted = true;
			attack.gameObject.SetActive(value: false);
		}
	}

	protected static ElementalBurst CreateBurst(GameObject givenPrefab, Vector2 givenPosition, string skillCategory = "", string skillID = "", int skillLevel = 1, float givenScale = 1f, bool isUltimate = false)
