using UnityEngine;

public class ExplosionOnKillChance : ModWithKills
{
	public static string staticID = "ExplosionOnKillChance";

	protected float explosionChance = 0.5f;

	protected float explosionRadius = 2.5f;

	protected override string ExtraInfo => PercentToStr(explosionChance, "+");

	public ExplosionOnKillChance()
	{
		ID = staticID;
		category = Category.Offense;
	}

	public override void HandleKillEvent(Entity givenEntity, AttackInfo givenInfo)
	{
		if (Random.value < explosionChance)
		{
			CreateExplosion(FlameBurst.burnSkillID, givenEntity.hurtBoxTransform.position);
		}
	}

	public void CreateExplosion(string skillID, Vector2 givenPosition)
	{
		FlameBurst.CreateBurst(givenPosition, parentSkillCategory, skillID, 1, explosionRadius);
		SoundManager.PlayWithDistAndSPR("BlazingBlitzEnd", givenPosition);
		PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(6, givenPosition);
		CameraController.ShakeCamera(0.25f);
	}
}
