using UnityEngine;

public class FireBomb : MonoBehaviour
{
	private bool markedForDestroy;

	private static GameObject _prefab;

	public Attack attack;

	public FollowTransform followTransform;

	public Animator anim;

	private ChaosQuickStopwatch fuseTimer;

	public float fuseTime = 0.75f;

	public Transform targetTrans;

	public Entity targetEntity;

	public bool fastAnimPlayed;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Effects/Fire/FireBomb.prefab");
			}
			return _prefab;
		}
	}

	private void Start()
	{
		anim.Play("Idle");
		fuseTimer = new ChaosQuickStopwatch(fuseTime);
		fuseTimer.IsRunning = true;
		if (targetTrans != null)
		{
			followTransform.followTransform = targetTrans;
		}
	}

	private void FixedUpdate()
	{
		if (markedForDestroy)
		{
			Object.Destroy(gameObject);
			return;
		}
		if (targetEntity == null || targetEntity.fsm.currentStateName.Contains("Dead"))
		{
			markedForDestroy = true;
			return;
		}
		if (fuseTimer.IsRunning)
		{
			if (!fastAnimPlayed && fuseTimer.TimePercentage >= 0.7f)
			{
				fastAnimPlayed = true;
				anim.Play("IdleFast");
			}
			return;
		}
		markedForDestroy = true;
		if (targetTrans != null)
		{
			attack.EnableForOneFrame();
			FireExplosion.SpawnExplosion(transform.position, 0.25f, 0.5f);
			SoundManager.PlayAudioWithDistance("ImpactFire", transform.position, null, 24f, -1f, 1.2f);
		}
	}

	public static void SpawnFireBomb(Vector3 spawnPos, string skillCategory, string skillID, Entity entity = null, float fuseTime = 1f, bool isEmpowered = false, Vector3? knockbackOverwriteVector = null)
	{
		if (!(entity == null))
		{
			FireBomb fireBomb = Globals.ChaosInst<FireBomb>(Prefab, null, spawnPos);
			fireBomb.targetTrans = entity.hurtBoxTransform;
			fireBomb.followTransform.followOffset = Vector3.up * 0.25f;
			if (entity is MovingStatue)
			{
				fireBomb.followTransform.followOffset = Vector3.up * 0.5f;
			}
			fireBomb.attack.SetAttackInfo(skillCategory, skillID, (!isEmpowered) ? 2 : 3);
			if (knockbackOverwriteVector.HasValue)
			{
				fireBomb.attack.knockbackOverwriteVector = knockbackOverwriteVector.Value;
			}
			fireBomb.fuseTime = fuseTime;
			fireBomb.targetEntity = entity;
		}
	}
