using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class ChargeFamiliar : Entity
{
	public class FollowState(string stateName, FSM parentFSM, ChargeFamiliar parentEntity) : State<ChargeFamiliar>(stateName, parentFSM, parentEntity)
	{
		private const float trackingDelay = 0.2f;

		private const float trackingInterval = 0.05f;

		private const int trackCount = 4;

		private int trackingIndex;

		private int checkIndex;

		private Vector3[] delayedParentPosition;

		private float distToParent;

		private float atkDist;

		private float followRadius;

		private Vector3 followOffset;

		private bool initOrbit;

		private float orbitDelay = 0.5f;

		private int orbitDelayStopwatchID;

		private WaitForSeconds waitForTracking = new WaitForSeconds(0.05f);

		public override void OnEnter()
		{
			parent.anim.Play("Idle");
			if (parent.parentTransform == null)
			{
				fsm.ChangeState("Dead");
				return;
			}
			parent.StartCoroutine(TrackParent());
			parent.closestTarget = null;
			followRadius = parent.movement.orbitRadius;
			followOffset = Vector3.one * Random.Range(-1f, 1f) * followRadius;
			followRadius *= followRadius;
			atkDist = Mathf.Pow(parent.attackFollowRadius, 2f);
			orbitDelayStopwatchID = ChaosStopwatch.Begin(orbitDelay);
		}

		public override void Update()
		{
			distToParent = Vector2.SqrMagnitude(parent.transform.position - parent.parentTransform.position);
			if (distToParent > followRadius)
			{
				parent.transform.position = Vector3.Lerp(parent.transform.position, delayedParentPosition[checkIndex] + followOffset, Time.deltaTime * 3f);
				initOrbit = false;
				ChaosStopwatch.Refresh(orbitDelayStopwatchID, orbitDelay);
			}
			else if (ChaosStopwatch.Check(orbitDelayStopwatchID))
			{
				if (!initOrbit)
				{
					initOrbit = true;
					parent.movement.InitOrbitAngle((parent.transform.position - parent.parentTransform.position).normalized);
					followOffset = Vector3.one * Random.Range(-1f, 1f) * parent.movement.orbitRadius;
				}
				else
				{
					parent.movement.OrbitTarget(parent.parentTransform.position);
				}
			}
			if (!parent.parentEntity.fsm.currentStateName.Contains("Dead") && !parent.parentEntity.fsm.currentStateName.Contains("Paused") && distToParent < atkDist && ChaosStopwatch.Check(parent.attackCDStopwatchID))
			{
				parent.closestTarget = Entity.GetClosestTarget(GameController.enemies, parent.parentTransform.position, parent.targettingRadius, playerTagOnly: false, parent.doNotTargetList);
				if (parent.closestTarget != null && Entity.HasLineOfSight(parent.transform.position, parent.closestTarget.hurtBoxPosition, parent.targettingRadius, ChaosCollisions.layerUpperWall))
				{
					fsm.ChangeState("Attack");
				}
			}
		}

		private IEnumerator TrackParent()
		{
			if (parent.trackingParent)
			{
				yield break;
			}
			parent.trackingParent = true;
			delayedParentPosition = new Vector3[4];
			trackingIndex = 0;
			while (parent.trackingParent && parent.parentTransform != null)
			{
				ref Vector3 reference = ref delayedParentPosition[trackingIndex];
				reference = parent.parentTransform.position;
				trackingIndex++;
				if (trackingIndex >= 4)
				{
					trackingIndex -= 4;
				}
				checkIndex = trackingIndex;
				yield return waitForTracking;
			}
		}
	}

	public class AttackState : State<ChargeFamiliar>
	{
		private bool inRange;

		private Vector2 startVector;

		private Vector3 endVector;

		private Vector3 attackVector;

		private int chargeUpStopwatchID;

		private int attackStopwatchID;

		private bool attackReady;

		private float atkDist;

		public AttackState(string stateName, FSM parentFSM, ChargeFamiliar parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			inRange = false;
			attackReady = false;
			atkDist = Mathf.Pow(parent.attackFollowRadius, 2f);
		}

		public override void Update()
		{
			if (!inRange)
			{
				if (parent.closestTarget != null && parent.closestTarget.hurtBoxTransform != null)
				{
					if (Vector2.SqrMagnitude(parent.transform.position - parent.parentTransform.position) > atkDist)
					{
						fsm.ChangeState(fsm.defaultStateName);
					}
					else if (parent.movement.MoveToTarget(parent.closestTarget.hurtBoxTransform, parent.attackRadius - 1f))
					{
						inRange = true;
						parent.anim.Play("ChargeUp");
						attackVector = (parent.closestTarget.hurtBoxTransform.position - parent.transform.position).normalized;
						endVector = attackVector * parent.attackRadius + parent.transform.position;
						parent.attack.knockbackOverwriteVector = attackVector;
						startVector = parent.transform.position;
						chargeUpStopwatchID = ChaosStopwatch.Begin(parent.chargeUpTime);
						attackStopwatchID = ChaosStopwatch.Begin(parent.chargeUpTime + 0.15f);
						SoundManager.PlayAudioWithDistance("AirWindup", parent.transform.position);
					}
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
				return;
			}
			if (!attackReady)
			{
				attackReady = true;
				parent.elemBoostManager.StartEmpowerEffect(overrideElement: parent.element, skillID: string.Empty);
			}
			if (!ChaosStopwatch.Check(chargeUpStopwatchID))
			{
				parent.targetLine.aimVector = attackVector;
				parent.targetLine.IsVisible(status: true);
				return;
			}
			parent.targetLine.IsVisible(status: false);
			if (!ChaosStopwatch.Check(attackStopwatchID))
			{
				parent.attack.collider.enabled = true;
				parent.transform.position = Vector3.Lerp(endVector, startVector, ChaosStopwatch.GetRemainingTime(attackStopwatchID) / 0.15f);
			}
			else
			{
				parent.attack.collider.enabled = false;
				parent.attackCDStopwatchID = ChaosStopwatch.Begin(parent.attackCooldown + Random.value);
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}

	public class ChargeFamiliarDeadState : State<ChargeFamiliar>
	{
		public ChargeFamiliarDeadState(string stateName, FSM parentFSM, ChargeFamiliar parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			parent.doNotTargetList.Remove(parent.gameObject);
			parent.attack.collider.enabled = false;
			parent.targetLine.IsVisible(status: false);
			parent.anim.Play("Dead");
		}
	}

