	public List<GameObject> doNotTargetList;

	public SpriteRenderer spriteOutlineRenderer;

	private bool trackingParent;

	public float attackFollowRadius = 7f;

	public float targettingRadius = 7f;

	public float attackRadius = 7f;

	public float chargeUpTime = 0.5f;

	public float attackCooldown = 2f;

	private int attackCDStopwatchID = -1;

	private TargetLine targetLine;

	[HideInInspector]
	public TargetInfo closestTarget;

	private ElementBoostManager elemBoostManager;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/ChargeFamiliar.prefab"));

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
		targetLine = transform.Find("TargetLine").GetComponent<TargetLine>();
		targetLine.maxRange = attackRadius;
		Object.DontDestroyOnLoad(gameObject);
	}

	public override void Start()
	{
		base.Start();
		elemBoostManager = Object.Instantiate(ElementBoostManager.Prefab).GetComponent<ElementBoostManager>();
		elemBoostManager.transform.SetParent(transform);
		elemBoostManager.transform.position = transform.position;
		InitFSM();
		targetLine.collisionLayerMask = 0;
	}

	public override void Update()
	{
		if (parentTransform == null)
		{
			fsm.ChangeState("Dead");
		}
		else
		{
			base.Update();
		}
	}

	public void HandleElement(ElementType newElement)
	{
		string newSkillID = string.Empty;
		switch (newElement)
		{
		case ElementType.Fire:
			newSkillID = "FireChargeFamiliar";
			movement.orbitRadius -= 0.5f;
			spriteOutlineRenderer.color = new Color(1f, 0.2f, 0f, 0.5f);
			spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(1f, 0.2f, 0f, 0.25f));
			break;
		case ElementType.Air:
			newSkillID = "AirChargeFamiliar";
			spriteOutlineRenderer.color = new Color(0.8f, 0.8f, 0.8f, 0.4f);
			spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0.8f, 0.8f, 0.8f, 0.15f));
			break;
		case ElementType.Earth:
			newSkillID = "EarthChargeFamiliar";
			movement.orbitRadius += 0.25f;
			spriteOutlineRenderer.color = new Color(0f, 1f, 0.2f, 0.5f);
			spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0f, 1f, 0.2f, 0.25f));
			break;
		case ElementType.Lightning:
			newSkillID = "LightningChargeFamiliar";
			movement.orbitRadius -= 0.25f;
			spriteOutlineRenderer.color = new Color(1f, 0.8f, 0f, 0.4f);
			spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(1f, 0.8f, 0f, 0.15f));
			break;
		case ElementType.Water:
			newSkillID = "WaterChargeFamiliar";
			movement.orbitRadius += 0.5f;
			spriteOutlineRenderer.color = new Color(0f, 0.8f, 1f, 0.4f);
			spriteOutlineRenderer.material.SetColor("_OutlineColor", new Color(0f, 0.8f, 1f, 0.15f));
			break;
		}
		element = newElement;
		if (parentEntity != null && parentEntity is Player)
		{
			attack.SetAttackInfo(parentEntity.skillCategory, newSkillID);
		}
	}

	public void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Follow";
		fsm.AddState(new FollowState("Follow", fsm, this));
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new ChargeFamiliarDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
}

