using Chaos.AnimatorExtensions;
using UnityEngine;

public class ChaosWeapon : Projectile
{
	private static GameObject prefab;

	public Movement movement;

	public bool releaseQueued;

	private string skillCat;

	private string skillID;

	private int eleIndex;

	private int posIndex;

	private Transform followTrans;

	private Vector3 followVec;

	private Vector3 followOffset;

	private Vector2 relPos;

	private Vector2 relVec;

	private float relTime;

	private int relStopwatchID;

	private float relLerpValue;

	private bool relCompleted;

	private Vector3 startRoteVec;

	private Vector3 endRoteVec;

	private bool spawnAnimPlayed;

	public Sprite[] eleSprites;

	private ParticleEffect lightningEffect;

	private ParticleEffect iceEffect;

	public GameObject fireEffectObj;

	public GameObject windEffectObj;

	private bool isBladeRight = true;

	private ElementType currentElement = ElementType.Chaos;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/ChaosWeapon.prefab"));

	public override void Start()
	{
		InitElement();
		base.Start();
	}

	public void InitElement()
	{
		projectileSpriteRenderer.sprite = eleSprites[eleIndex];
		switch (eleIndex)
		{
		case 0:
			rotation = true;
			break;
		case 1:
			currentElement = ElementType.Fire;
			fireEffectObj.SetActive(value: true);
			break;
		case 2:
			currentElement = ElementType.Air;
			rotation = true;

			rotation = true;
			windEffectObj.SetActive(value: true);
			break;
		case 3:
			currentElement = ElementType.Earth;
			break;
		case 4:
		{
			currentElement = ElementType.Lightning;
			lightningEffect = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
			lightningEffect.followTransform = transform;
			lightningEffect.reqFollowTrans = true;
			ParticleEffect particleEffect = lightningEffect;
			float? emissionRate = 5f;
			ParticleSystemOverride radiusZero = ParticleEffectOverrides.RadiusZero;
			particleEffect.Play(emissionRate, null, radiusZero);
			break;
		}
		case 5:
			currentElement = ElementType.Water;
			rotation = true;
			iceEffect = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
			iceEffect.followTransform = transform;
			iceEffect.reqFollowTrans = true;
			iceEffect.Play(5f);
			break;
		case 6:
			break;
		}
	}

	public override void Update()
	{
		base.Update();
		if (!spawnAnimPlayed && anim.AnimPlayed())
		{
			spawnAnimPlayed = true;
			anim.Play("Idle", -1, Random.value);
			anim.AdjustAnimSpeed("Idle", Random.Range(0.75f, 1.625f));
		}
	}

	public override void FixedUpdate()
	{
		if (relCompleted)
		{
			base.FixedUpdate();
		}
		else if (releaseQueued)
		{
			relLerpValue = ChaosStopwatch.GetTimePercentage(relStopwatchID);
			transform.position = Vector2.Lerp(transform.position, relPos, relLerpValue);
			if (rotation)
			{
				projectileSprite.transform.localEulerAngles = Vector3.Lerp(Vector3.zero, rotationVector, relLerpValue);
			}
			else
			{
				transform.localEulerAngles = Vector3.Lerp(startRoteVec, endRoteVec, relLerpValue * 1.25f);
			}
			if (relLerpValue >= 1f)
			{
				relCompleted = true;
				moveVector = relVec;
				attackBox.SetAttackInfo(skillCat, skillID);
				attackBox.collider.enabled = true;
				wallCollider.enabled = true;
				disableOnHit = true;
				flyTime = 0.35f;
				RefreshFlightTime();
				PlayShootEffects();
				if (rotation)
				{
					rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
				}
			}
			anim.Play("Attack", -1, 0f);
		}
		else if (followTrans != null)
		{
			movement.MoveToTarget(followTrans.position + followOffset);
		}
	}

	public override void ResetProjectile()
	{
		if (!releaseQueued)
		{
			FireWeapon(transform.position, (followVec - followOffset * 0.25f).normalized);
			return;
		}
		base.ResetProjectile();
		if (eleIndex > 0 && eleIndex < 6)
		{
			skillID += currentElement;
		}
		Vector2 vector = transform.position;
		ElementalBurst elementalBurst;
		switch (eleIndex)
		{
		case 0:
			elementalBurst = NeutralBurst.CreateBurst(vector, skillCat, skillID, 3, 2.5f);
			SoundManager.PlayWithDistAndSPR("MetalBreak", vector);
			break;
		case 1:
			elementalBurst = FlameBurst.CreateBurst(vector, skillCat, skillID, 1, 2.5f);
			SoundManager.PlayWithDistAndSPR("FireArcEnd", vector);
			if (fireEffectObj != null)
			{
				fireEffectObj.SetActive(value: false);
			}
			break;
		case 2:
			elementalBurst = WindBurst.CreateBurst(vector, skillCat, skillID, 1, 2.5f);
			SoundManager.PlayWithDistAndSPR("WindBlastDeep", vector, 1.1f);
			if (windEffectObj != null)
			{
				windEffectObj.SetActive(value: false);
			}
			break;
		case 3:
			elementalBurst = EarthBurst.CreateBurst(vector, skillCat, skillID, 1, 2.5f);
			SoundManager.PlayWithDistAndSPR("ChessPiece", vector);
			break;
		case 4:
			elementalBurst = LightningBurst.CreateBurst(vector, skillCat, skillID, 1, 2.5f);
			SoundManager.PlayWithDistAndSPR("LightningBurst", vector);
			if (lightningEffect != null)
			{
				lightningEffect.followTransform = null;
				lightningEffect.reqFollowTrans = false;
				lightningEffect.Stop();
			}
			break;
		case 5:
			elementalBurst = IceBurst.CreateBurst(vector, skillCat, skillID, 1, 2.5f);
			SoundManager.PlayWithDistAndSPR("IceExplode", vector);
			break;
		default:
			elementalBurst = ChaoticBurst.CreateBurst(vector, skillCat, skillID, 2, 2.5f);
			SoundManager.PlayWithDistAndSPR("ChaosShot", vector);
			break;
		}
		elementalBurst.attack.knockbackOverwriteVector = relVec;
	}

	public void SetVars(string givenCat, string givenID, Transform givenTrans, float givenDur, int givenEleIndex, int givenPosIndex)
	{
		skillCat = givenCat;
		skillID = givenID;
		followTrans = givenTrans;
		flyTime = givenDur;
		eleIndex = givenEleIndex;
		posIndex = givenPosIndex;
	}

	public void UpdateOffset(Vector2 givenVec)
	{
		followVec = givenVec;
		followOffset = Globals.GetRotatedCircleVector(16, posIndex - 3, -givenVec) * 2f;
		SetDirection(givenVec.x < 0f);
	}

	public void FireWeapon(Vector2 givenPos, Vector2 givenVec)
	{
		releaseQueued = true;
		relTime = Random.Range(0.45f, 0.55f);
		relStopwatchID = ChaosStopwatch.Begin(relTime);
		relPos = givenPos + (givenPos - (Vector2)transform.position).normalized * 0.8f;
		relVec = (givenPos + givenVec * 6f - relPos).normalized;
		startRoteVec = transform.localEulerAngles;
		endRoteVec = Globals.GetRotationVector(relVec);
		endRoteVec.z += ((!(endRoteVec.z - startRoteVec.z > 0f)) ? (-360f) : 360f);
		RefreshFlightTime();
		SetDirection(relVec.x < 0f);
		if (rotation)
		{
			rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f * relTime);
			SoundManager.PlayAudioWithDistance("StandardSpin", transform.position);
		}
		else
		{
			SoundManager.PlayWithDistAndSPR("StandardSpinSingle", transform.position, 0.9f);
		}
	}

	private void PlayShootEffects()
	{
		Vector2 vector = transform.position;
		switch (eleIndex)
		{
		case 0:
			PoolManager.GetPoolItem<ParticleEffect>("MetalSparkEmitter").Emit(6, vector);
			SoundManager.PlayAudioWithDistance("StandardHeavySwing", vector);
			break;
		case 1:
		{
			FireBurst poolItem2 = PoolManager.GetPoolItem<FireBurst>();
			int? particleCount = 3;
			Vector3? position = vector;
			Vector3? localEulerAngles = Globals.GetRotationVector(relVec);
			poolItem2.EmitSingle(particleCount, position, null, localEulerAngles);
			SoundManager.PlayAudioWithDistance("FireballCast", vector);
			break;
		}
		case 2:
			PoolManager.GetPoolItem<ParticleEffect>("SpinningCircleBurst").Emit(1, vector, localEulerAngles: Globals.GetRotationVector(relVec), overrides: ParticleEffectOverrides.StartLifeTime0p5);
			SoundManager.PlayWithDistAndSPR("WindBlastSharp", vector, 1.1f);
			break;
		case 3:
		{
			RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
			RockDebrisType debrisType = RockDebrisType.Default;
			int? particleCount = 4;
			Vector3? position = vector;
			Vector3? localEulerAngles = Globals.GetRotationVector(relVec);
			poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			SoundManager.PlayAudioWithDistance("ThrowBoulder", vector);
			break;
		}
		case 4:
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, vector);
			SoundManager.PlayWithDistAndSPR("TeleStrike", vector, 1.25f);
			break;
		case 5:
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(6, vector);
			SoundManager.PlayWithDistAndSPR("FrostSwing", vector);
			break;
		case 6:
			PoolManager.GetPoolItem<ParticleEffect>("ChaosLightningBurst").Emit(2, vector);
			SoundManager.PlayWithDistAndSPR("ChaosBeamStart", vector);
			break;
		}
	}

	private void SetDirection(bool givenIsLeft)
	{
		if (givenIsLeft)
		{
			if (isBladeRight)
			{
				isBladeRight = false;
				transform.localScale = Globals.Vector3NegativeX;
			}
		}
		else if (!isBladeRight)
		{
			isBladeRight = true;
			transform.localScale = Vector3.one;
		}
	}
}
