public class UseChaosWeapons : UseBuffSkill
{
	public new static string staticID = "UseChaosWeapons";

	private const int MaxCount = 7;

	private static int[] arrangeArray = new int[7] { 0, 6, 1, 5, 2, 4, 3 };

	private ChaosWeapon[] cwArray = new ChaosWeapon[7];

	private ChaosWeapon currentCW;

	private Vector2 curDirVec;

	private int ActiveIndex
	{
		get
		{
			for (int i = 0; i < 7; i++)
			{
				if (cwArray[i] != null && !cwArray[i].releaseQueued)
				{
					return i;
				}
			}
			return -1;
		}
	}

	public UseChaosWeapons(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		isProjectileSkill = true;
		whileStopwatch.SetDelay(0.125f);
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		Vector2 vector = (Vector2)parent.attackOriginTrans.position - inputVector;
		ChaosBurst.Spawn(vector, 3);
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(vector, "Depart", 0.2f);
		SoundManager.PlayWithDistAndSPR("Teleport", vector);
		SoundManager.PlayWithDistAndSPR("ChaosSummon", vector);
		SoundManager.PlayWithDistAndSPR("SlashIntro", vector, 1.2f);
		parent.movement.moveVector = Entity.GetFacingDirectionVector(parent.facingDirection);
		for (int i = 0; i < 7; i++)
		{
			cwArray[i] = CreateChaosWeapon(vector, i);
		}
		CameraController.ShakeCamera(0.3f);
	}

	public override void SetBuffStatus(bool givenStatus)
	{
		base.SetBuffStatus(givenStatus);
		Player player = parent;
		player.skillEnterEventHandlers = (SkillEventHandler)Delegate.Remove(player.skillEnterEventHandlers, new SkillEventHandler(OnSkillEnter));
		Player player2 = parent;
		player2.skillExecEventHandlers = (SkillEventHandler)Delegate.Remove(player2.skillExecEventHandlers, new SkillEventHandler(OnSkillExec));
		if (givenStatus)
		{
			Player player3 = parent;
			player3.skillEnterEventHandlers = (SkillEventHandler)Delegate.Combine(player3.skillEnterEventHandlers, new SkillEventHandler(OnSkillEnter));
			Player player4 = parent;
			player4.skillExecEventHandlers = (SkillEventHandler)Delegate.Combine(player4.skillExecEventHandlers, new SkillEventHandler(OnSkillExec));
		}
	}

	public override void WhileBuffActive()
	{
		curDirVec = parent.rigidbody2D.velocity.normalized;
		if (curDirVec == Vector2.zero)
		{
			curDirVec = Entity.GetFacingDirectionVector(parent.facingDirection);
		}
		for (int i = 0; i < 7; i++)
		{
			if (cwArray[i] != null)
			{
				cwArray[i].UpdateOffset(curDirVec);
			}
		}
	}

	private ChaosWeapon CreateChaosWeapon(Vector2 givenPos, int givenIndex)
	{
		currentCW = (ChaosWeapon)Projectile.CreateProjectile(parent, ChaosWeapon.Prefab, givenPos);
		currentCW.SetVars(parent.skillCategory, skillID, parent.attackOriginTrans, buffDuration, givenIndex, arrangeArray[givenIndex]);
		currentCW.UpdateOffset(inputVector);
		return currentCW;
	}

	private void OnSkillEnter(SkillState givenSkill)
	{
		if (givenSkill != null && givenSkill.isUltimate)
		{
			ReleaseAllWeapons(parent.attackOriginTrans.position, parent.GetInputVector(faceInputVector: false));
		}
	}

	private void OnSkillExec(SkillState givenSkill)
	{
		if (givenSkill != null && !givenSkill.isUltimate && !givenSkill.isDash)
		{
			curDirVec = parent.GetInputVector(faceInputVector: false);
			ReleaseChaosWeapon(parent.attackOriginTrans.position, curDirVec);
		}
	}

	private void ReleaseAllWeapons(Vector2 givenPos, Vector2 givenVec)
	{
		for (int i = 0; i < 7; i++)
		{
			if (cwArray[i] != null && !cwArray[i].releaseQueued)
			{
				cwArray[i].FireWeapon(givenPos, givenVec);
				cwArray[i] = null;
			}
		}
		durationStopwatch.IsRunning = false;
	}

	private void ReleaseChaosWeapon(Vector2 givenPos, Vector2 givenVec)
	{
		int activeIndex = ActiveIndex;
		if (activeIndex > -1)
		{
			cwArray[activeIndex].FireWeapon(givenPos, givenVec);
			cwArray[activeIndex] = null;
		}
		if (ActiveIndex < 0)
		{
			durationStopwatch.IsRunning = false;
		}
	}
}

