public class OnParryItem : Item
{
	private BoolVarStatMod parryMod;

	public bool IsNewParry => parentPlayer != null && parentPlayer.fsm.previousStateName != Player.ParryState.staticID;

	public override void Activate()
	{
		SetHandlers(givenStatus: true);
	}

	public override void Deactivate()
	{
		SetHandlers(givenStatus: false);
	}

	public bool IsMeleeParry(AttackInfo givenInfo)
	{
		return givenInfo != null && Vector2.SqrMagnitude(givenInfo.attackerPosition - givenInfo.targetPosition) < 7f;
	}

	public virtual void SetHandlers(bool givenStatus)
	{
		if (parryMod == null)
		{
			parryMod = new BoolVarStatMod(ID, newModValue: true);
		}
		if (SetParentAsPlayer())
		{
			parentPlayer.SetParryCheckStatus(parryMod, givenStatus);
			Player player = parentPlayer;
			player.parryEventHandlers = (Player.ParryEventHandler)Delegate.Remove(player.parryEventHandlers, new Player.ParryEventHandler(OnParry));
			if (givenStatus)
			{
