	{
		atkBox = Globals.ChaosInst<Attack>(Attack.CirclePrefab, transform);
		atkBox.collider.transform.localScale = new Vector3(0.25f, 0.25f, 1f);
		atkBox.SetAttackInfo(skillCategory, skillID, skillLevel);
		atkBox.collider.enabled = false;
	}

	private void FixedUpdate()
	{
		if (atkBox.collider.enabled)
		{
			if (!atkBoxDisableQueued)
			{
				atkBoxDisableQueued = true;
				return;
			}
			atkBoxDisableQueued = false;
			atkBox.collider.enabled = false;
		}
	}

