	{
		if (parentEntity == null || (parentHealth != null && parentHealth.healthStat.CurrentValue <= 0f) || parentEntity.fsm.currentStateName.Contains("Dead") || parentEntity.fsm.currentStateName.Contains("Paused") || !ChaosStopwatch.Check(freezeDelayStopwatchID))
