	{
		OnTargetHit(other);
		wallCollider.enabled = false;
		base.HandleWallCollision(other);
		SoundManager.PlayWithDistAndSPR("ImpactEarth", transform.position);
	}

	public override void ResetProjectile()
	{
		if (forcedReturn || !targetHit || atkCompleted)
		{
			Attack attack = attackBox;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
			Vector2 vector = transform.position;
			if (isEmpowered)
			{
				EarthBurst.CreateBurst(vector, attackBox.ChangeAttackInfoLevel(2), 1.5f).attack.knockbackOverwriteVector = moveVector;
				SoundManager.PlayWithDistAndSPR("EarthExplosionShort", vector);
			}
			else
			{
				RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
				RockDebrisType debrisType = RockDebrisType.Default;
				int? particleCount = 2;
				Vector3? position = vector;
				Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
				poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
				SoundManager.PlayWithDistAndSPR("EarthDust", vector);
			}
			partSys.Stop();
			partSys.transform.SetParent(null);
			UnityEngine.Object.Destroy(partSys.gameObject, 0.35f);
			base.ResetProjectile();
		}
	}

	private void OnTargetHit(Collider2D col)
	{
		speedStopwatch.Refresh();
		speedCompleted = false;
		targetHit = true;
	}
}

