	spriteLight.intensity = givenValue * 2f;
	lightningEmitter.effectEmitter.emissionRate = Mathf.Lerp((!isSecondary) ? 0f : 2f, (!isSecondary) ? 30f : 8f, givenValue);
	if (!isUltimate)
	{
		attackBox.atkInfo.knockbackMultiplier = calcKBMultiplier * givenValue;
	}
}

