using UnityEngine;
public class VineTrap : MonoBehaviour
{
	private static GameObject prefab;
	private Animator anim;
	private Vector3 movePos;
	private Entity rootedEntity;
	private int idleStopwatchID = -1;
	private bool spawnAnimPlayed;
	[HideInInspector]
	public Attack attack;
	[HideInInspector]
	public float lifeTime = 2f;
	[HideInInspector]
	public bool useLifeTime;
	private int lifeStopwatchID;
	[HideInInspector]
	public bool markedForDestroy;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/VineTrap.prefab"));
	private void Awake()
	{
		anim = GetComponent<Animator>();
		attack = GetComponentInChildren<Attack>();
		movePos = Vector3.zero;
	}
	private void Start()
	{
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(EntityEventHandler));
		if (useLifeTime)
		{
			lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
		}
	}
	private void Update()
	{
		if (useLifeTime && ChaosStopwatch.Check(lifeStopwatchID))
		{
			useLifeTime = false;
			DestroyVine();
		}
		if (!markedForDestroy && anim.AnimPlayed() && (!spawnAnimPlayed || ChaosStopwatch.Check(idleStopwatchID)))
		{
			spawnAnimPlayed = true;
			idleStopwatchID = ChaosStopwatch.Begin(UnityEngine.Random.Range(0.75f, 1.5f));
		}
		if (rootedEntity != null)
		{
			MoveRootedEntity();
		}
	}
	private void EntityEventHandler(Entity otherEntity)
	{
		if (otherEntity != null)
		{
			attack.enabled = false;
			if (otherEntity.health == null || otherEntity.health.ignoreGrab)
			{
				DestroyVine();
				return;
			}
			anim.Play("Grab", -1, 0f);
			rootedEntity = otherEntity;
			movePos = transform.position;
			SoundManager.PlayAudioWithDistance("VineWhip", transform.position);
		}
	}
	private void MoveRootedEntity()
	{
		if (rootedEntity != null && movePos != Vector3.zero && Vector3.Distance(rootedEntity.transform.position, movePos) > 0.15f)
		{
			rootedEntity.rigidbody2D.MovePosition(movePos);
		}
	}
	public void EmitSpawnEffect()
	{
		if (!markedForDestroy)
		{
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(RockDebrisType.Default, 2, transform.position, RockDebrisEmitter.SmallCircleExplosionOverride, null, 0f, -2f);
		}
	}
	public void DestroyVine()
	{
		if (!markedForDestroy)
		{
			markedForDestroy = true;
			if (anim != null)
			{
				anim.Play("Dead", -1, 0f);
			}
			string audioID = "VineWaveEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
	}
}

