		{
			parent = parentEntity;
		}

		public override void OnEnter()
		{
			if (!parent.IsRooted && parent.health.lastAttack != null)
			{
				incomingAttack = parent.health.lastAttack;
				if (incomingAttack.skillID == skillID && !parent.IgnoreWallToWallCollisions)
				{
					fsm.ChangeState("Dead");
					return;
				}
				parent.movement.EndMovement();
				parent.WallStruck(incomingAttack.knockbackVector, incomingAttack.skillCategory, incomingAttack.damage, incomingAttack.knockbackMultiplier);
