			if (spawnExplosionOnDestroy && !explosionSpawned)
			{
				explosionSpawned = true;
				EarthBurst.CreateBurst(transform.position, currentSkillCategory, skillID, 1, 2.5f);
			}
		}
	}

	private void HandleDecay()
	{
		if (!removedFromList && ChaosStopwatch.GetRemainingTime(lifeStopwatchID) < 1f)
		{
			removedFromList = true;
			knockbackWallList.Remove(this);
		}
		if (!isMoving)
		{
			attack.collider.enabled = false;
			return;
		}
		currentMagnitude = rigidbody2D.velocity.magnitude;
		isMoving = currentMagnitude > minMagnitudeForDmg;
		if (!emitTimer.IsRunning)
		{
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int num = 3;
			float z = Globals.GetRotationVector(-movement.moveVector).z;
			float startSpeed = 1f;
