			attack.knockbackMultiplierOverride = attack.damageOverride;
		}
	}

	public void ClaimWall()
	{
		StartCoroutine(HandleClaimDuration());
	}

	public IEnumerator HandleClaimDuration()
	{
		int claimStopwatchID = ChaosStopwatch.Begin(claimDuration);
		wallClaimed = true;
		while (wallClaimed && !ChaosStopwatch.Check(claimStopwatchID))
		{
			yield return null;
		}
		wallClaimed = false;
	}

	public void OnImpact(Collider2D other)
	{
		attack.collider.enabled = false;
		if (destroyOnImpact)
		{
