			IsRooted = false;
			attack.collider.enabled = true;
			currentSkillCategory = newCategory;
			attack.SetAttackInfo(currentSkillCategory, currentSkillID);
			initDamage = damageOverride;
			forceOverride = Mathf.Clamp((!(forceOverride > 0f)) ? 100f : forceOverride, 100f, 1000f);
			movement.moveVector = newMoveVector;
			movement.MoveToMoveVector(forceOverride, useAddForce: true);
			initMagnitude = rigidbody2D.velocity.magnitude;
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, transform.position + new Vector3(0f, 1.25f, 0f));
			wallClaimed = false;
		}
	}

	public override void Break()
	{
		health.CurrentHealthValue = 0;
		if (!removedFromList)
		{
			knockbackWallList.Remove(this);
		}
		rigidbody2D.isKinematic = false;
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(3, transform.position + new Vector3(0f, 1.25f, 0f));
		SoundManager.PlayAudioWithDistance("EarthCrumble", transform.position);
		base.Break();
	}
