public class UseCoiledVine : SkillState
{
	public new static string staticID = "UseCoiledVine";

	private int maxChargeReq = 3;

	private float chargeTime = 0.125f;

	private int chargeStopwatchID;

	private bool chargeStarted;

	private bool chargeCompleted;

	private bool holdReleaseBuffered;

	private bool holdReleaseAllowed;

	private ChaosQuickStopwatch effectStopwatch = new ChaosQuickStopwatch(0.1f);

	private Vector2 currentPosition;

	private Vector2 perpendVec;

	private Vector2 atkVector;

	private float spawnOffsetInc = 0.1f;

	private int spreadValue = 75;

	private int vineCount = 2;

	private float atkRange = 5f;

	private float atkWidth = 2f;

	private int atkLevel = 1;

	private LightningStream currentLS;

	public override string OnEnterAnimStr => parent.ForehandAnimStr;

	public override string OnHoldAnimStr => parent.ForehandAnimStr;

	public UseCoiledVine(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isHoldSkill = true;
		SetAnimTimes(0f, 0f, 0.3f, 0.8f, 0.9f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.hud.castBar.EndCast();
		chargeStarted = false;
		chargeCompleted = false;
		holdReleaseAllowed = false;
		holdReleaseBuffered = false;
	}

	public override void HandleHoldButton()
	{
		if (!holdReleaseBuffered)
		{
			inputVector = GetInputVector();
		}
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
		holdReleased = !parent.inputDevice.GetButton("Skill" + skillSlot);
		if (!effectStopwatch.IsRunning)
		{
			effectStopwatch.IsRunning = true;
			PlayChargeVisual();
		}
		if (!chargeStarted)
		{
			chargeStarted = true;
			chargeStopwatchID = ChaosStopwatch.Begin(chargeTime, useInterval: true, chargeTime, maxChargeReq);
			parent.hud.castBar.StartCast(ChaosStopwatch.Begin(chargeTime * (float)maxChargeReq + 0.025f), givenStatus: true);
		}
		if (!chargeCompleted)
		{
			switch (ChaosStopwatch.CheckInterval(chargeStopwatchID))
			{
			case StopwatchState.Ready:
				holdReleaseAllowed = true;
				break;
			case StopwatchState.Done:
				chargeCompleted = true;
				break;
			}
		}
		if (holdReleased)
		{
			holdReleaseBuffered = true;
			if (!holdReleaseAllowed)
			{
				holdReleased = false;
			}
		}
		else
		{
			holdReleased = holdReleaseBuffered;
		}
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		parent.anim.PlayDirectional(parent.ForehandAnimStr, -1, animExecTime);
		parent.hud.castBar.EndCast();
		CreateCoiledVine();
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
		parent.hud.castBar.EndCast();
	}

	private void PlayChargeVisual()
	{
	}

	private void CreateCoiledVine()
	{
		currentPosition = parent.attackOriginTrans.position;
		perpendVec = Globals.GetPerpendicular(inputVector);
		if (chargeCompleted)
		{
			spreadValue = 90;
			vineCount = 3;
			atkRange = 7f;
			atkWidth = 2.5f;
			atkLevel = 2;
		}
		else
		{
			spreadValue = 75;
			vineCount = 2;
			atkRange = 5f;
			atkWidth = 2f;
			atkLevel = 1;
		}
		for (int i = -vineCount; i <= vineCount; i++)
		{
			atkVector = Globals.GetRotatedCircleVector(spreadValue, i, inputVector) * atkRange;
			currentLS = ChaosInst<LightningStream>(LightningStream.Prefab, currentPosition + perpendVec * i * spawnOffsetInc);
			currentLS.targetLocation = currentPosition + atkVector;
			currentLS.hitCount = 1;
			if (i == 0)
			{
				currentLS.attackWidth = atkWidth;
				currentLS.attack.SetAttackInfo(parent.skillCategory, skillID, atkLevel);
				currentLS.attack.knockbackOverwriteVector = inputVector;
			}
		}
	}
}

