		currentBoulder.waitTime = (float)maxHitCount * hitInterval * 0.75f;
		currentBoulder.skipFirstAttack = true;
		currentBoulder.useAltSprite = true;
		currentBoulder.transform.localScale = new Vector3(1.5f, 1.5f, 1f);
		currentBoulder.riseHeight = 2.5f;
