public class VinePullProjectile : Projectile
{
	private static GameObject _prefab;
	public Transform curTargetTrans;
	private Vector3 curTargetPos;
	private VinePull curVine;
	public Transform parentTrans;
	public Vector2 moveVec;
	public string vineSkillCat;
	public string vineSkillID;
	public int vineSkillLevel;
	public bool empowered;
	public bool activated;
	private bool targetFound;
	private List<GameObject> targetList;
	private List<GameObject> curTargets;
	private Enemy tempEnemy;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/VinePullProjectile.prefab");
			}
			return _prefab;
		}
	}
	public override void Awake()
	{
		base.Awake();
		attackBox.enabled = false;
	}
	public override void Start()
	{
		base.Start();
		if (parentTrans == null)
		{
			parentTrans = transform;
		}
		if (targetList == null)
		{
			targetList = GameController.enemies;
		}
	}
	public void FindTargets()
	{
		List<GameObject> list = targetList;
		Vector3 position = parentTrans.position;
		float range = 4.25f;
		int layerUpperWallAndObst = ChaosCollisions.layerUpperWallAndObst;
		curTargets = Entity.GetAllTargetsInRange(list, position, range, playerTagOnly: false, null, null, requireLOS: true, layerUpperWallAndObst);
		for (int i = 0; i < curTargets.Count; i++)
		{
			curTargetTrans = null;
			curTargetPos = Vector3.zero;
			tempEnemy = curTargets[i].GetComponentInParent<Enemy>();
			if (!(tempEnemy == null) && !(tempEnemy.hurtBoxTransform == null))
			{
				curTargetTrans = tempEnemy.hurtBoxTransform;
				curVine = PoolManager.GetPoolItem<VinePull>("VinePull");
				curVine.Initialize(parentTrans, curTargetTrans, curTargetPos, Vector2.zero, moveVec, vineSkillCat, vineSkillID, vineSkillLevel, empowered);
				curVine.stopRotateOnPull = true;
				targetFound = true;
			}
		}
	}
	public override void ResetProjectile()
	{
		if (!activated)
		{
			base.ResetProjectile();
			gameObject.SetActive(value: true);
			FindTargets();
			activated = true;
			rotation = false;
			if (targetFound)
			{
				Object.Destroy(gameObject, 0.25f);
			}
			else
			{
				Object.Destroy(gameObject);
			}
		}
	}
}

