		if (isSmallVer)
		{
			anim.Play("RetractSmall", -1, 0f);
		}
		else
		{
			anim.Play("Retract", -1, 0f);
		}
		pullAnimStarted = true;
	}
	private void Update()
	{
		if (!initialized || destroyQueued)
		{
			return;
		}
		RotateTowardTarget();
		if (!pullAnimStarted)
		{
			if (anim.AnimPlayed())
			{
				Retract();
			}
		}
		else if (anim.AnimPlayed())
		{
			if (!lostTarget && !isSmallVer && isEmpowered)
			{
				skillLevel++;
				CreateAttack();
			}
			if (!resetAfterAtk)
			{
				destroyQueued = true;
				Object.Destroy(gameObject, 1f);
			}
			else
			{
				Reset();
			}
		}
	}
}

using UnityEngine;
public class RockBarrage : MonoBehaviour
{
	private static GameObject prefab;
	public Attack attack;
	public float atkRadius = 2f;
