	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/RockBarrage.prefab");
			}
			return prefab;
		}
	}
	private void Start()
	{
		attack.transform.localScale = new Vector3(atkRadius, atkRadius, 1f);
		lifeTime = (float)maxHitCount * hitInterval;
		lifeStopwatch = new ChaosQuickStopwatch(lifeTime * 1.2f);
		lifeStopwatch.IsRunning = true;
		hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
		for (int i = 0; i < maxCubeCount; i++)
		{
			currentCube = Globals.ChaosInst<EarthBossCube>(EarthBossCube.Prefab, null, transform.position + (Vector3)Random.insideUnitCircle * Random.Range(atkRadius * 0.7f, atkRadius * 0.8f));
			currentCube.riseTimeMin = 0.05f;
			currentCube.riseTimeMax = 0.1f;
			currentCube.endHeightMin = 2f;
			currentCube.endHeightMax = 3.5f;
			currentCube.autoDrop = true;
			currentCube.dropDelay = lifeTime * 0.7f * (float)i / (float)maxCubeCount;
			currentCube.transform.SetParent(transform);
			currentCube.useSmallCrack = true;
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			float z = Globals.GetRotationVector(Vector3.up).z;
			Vector3? emitPosition = currentCube.transform.position;
			poolItem.EmitDirBurst(10, z, 0.75f, -1f, 1.5f, emitPosition);
		}
	}
	private void FixedUpdate()
	{
		if (!lifeStopwatch.IsRunning)
		{
			Disable();
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attack.collider.enabled = true;
			break;
		case StopwatchState.Ready:
			attack.collider.enabled = false;
			break;
		case StopwatchState.Done:
			Disable();
			break;
		}
	}
	private void Disable()
	{
		Object.Destroy(gameObject);
	}
}

using UnityEngine;
public class BoulderDrop : MonoBehaviour
{
	private static GameObject prefab;
	private Vector2 currentPosition;
	private Transform spriteTrans;
	private SpriteRenderer sprite;
	[HideInInspector]
	public Attack attack;
	public Sprite altSprite;
	public bool useAltSprite;
	private CircleCollider2D atkCollider;
	private ParticleSystem explosionEmitter;
	public float riseHeight = 4f;
	private float startHeight;
	public float waitTime = 0.15f;
	public bool skipFirstAttack;
	private ChaosQuickStopwatch riseStopwatch = new ChaosQuickStopwatch(0.25f);
	private ChaosQuickStopwatch waitStopwatch;
	private ChaosQuickStopwatch fallStopwatch = new ChaosQuickStopwatch(0.0625f);
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.1f);
	private bool riseComplete;
	private bool waitComplete;
	private bool fallComplete;
	private bool atkComplete;
	private Vector2 lerpedPosition = Vector2.zero;
	private float lerpValue;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/BoulderDrop.prefab"));
	private void Awake()
	{
		attack = transform.Find("Attack").GetComponent<Attack>();
		atkCollider = attack.transform.GetComponent<CircleCollider2D>();
		spriteTrans = transform.Find("Sprite");
		sprite = spriteTrans.GetComponent<SpriteRenderer>();
		startHeight = spriteTrans.localPosition.y;
		explosionEmitter = transform.Find("ExplosionEmitter").GetComponent<ParticleSystem>();
	}
	private void Start()
	{
		currentPosition = transform.position;
		riseStopwatch.IsRunning = true;
		waitStopwatch = new ChaosQuickStopwatch(waitTime);
		string audioID = "SummonRock";
		Vector2? soundOrigin = currentPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition);
		if (useAltSprite)
		{
			sprite.sprite = altSprite;
		}
		if (!skipFirstAttack)
		{
			ActivateAttack(1);
		}
	}
	private void FixedUpdate()
	{
		if (!atkComplete && !atkStopwatch.IsRunning)
		{
			atkComplete = true;
			atkCollider.enabled = false;
		}
		if (!riseComplete)
		{
			lerpValue = riseStopwatch.TimePercentage;
			lerpValue = lerpValue * lerpValue * (3f - 2f * lerpValue);
			lerpedPosition.y = Mathf.Lerp(startHeight, riseHeight, lerpValue);
			spriteTrans.localPosition = lerpedPosition;
			if (lerpValue > 0.75f)
			{
				sprite.sortingLayerName = "UI";
			}
			if (lerpValue >= 1f)
			{
				riseComplete = true;
				waitStopwatch.IsRunning = true;
			}
		}
		else if (!waitComplete)
		{
			lerpValue = waitStopwatch.TimePercentage;
			if (lerpValue >= 1f)
			{
				waitComplete = true;
				fallStopwatch.IsRunning = true;
			}
		}
		else
		{
			if (fallComplete)
			{
				return;
			}
			lerpValue = fallStopwatch.TimePercentage;
			lerpedPosition.y = Mathf.Lerp(riseHeight, startHeight, lerpValue);
			spriteTrans.localPosition = lerpedPosition;
			if (lerpValue >= 1f)
			{
				fallComplete = true;
				ActivateAttack(2);
				spriteTrans.gameObject.SetActive(value: false);
				explosionEmitter.Play();
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 100;
				Vector3? emitPosition = currentPosition;
				poolItem.EmitCircle(particleCount, 1f, -1f, -1f, emitPosition);
				string audioID = "GroundSlam";
				Vector2? soundOrigin = currentPosition;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
				PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, currentPosition);
				CameraController.ShakeCamera(0.3f);
				if (gameObject != null)
				{
					Object.Destroy(gameObject, 1f);
				}
			}
		}
	}
	private void ActivateAttack(int givenLevel)
	{
		atkCollider.radius = ((givenLevel != 1) ? 2f : 1f);
		atkComplete = false;
		atkCollider.enabled = true;
		atkStopwatch.IsRunning = true;
		attack.ChangeAttackInfoLevel(givenLevel);
	}
}

using System;
using UnityEngine;
public class LightningComboProjectile : Projectile
{
	private static GameObject prefab;
	public Sprite[] sprites;
	private Entity targetEntity;
	private bool targetHit;
	private int maxHitCount = 5;
	public float hitInterval = 0.1f;
	private int hitStopwatchID;
	private int curHitCount;
	public bool isEmpowered;
	private LightningShadow currentShadow;
	public FacingDirection facingDir;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/LightningComboProjectile.prefab"));
	public override void Awake()
	{
		base.Awake();
		projectileSpriteRenderer.material.SetFloat("_PaletteIndex", 6f);
	}
	public override void Start()
	{
		base.Start();
		if (isEmpowered)
		{
			maxHitCount += 2;
			attackBox.ChangeAttackInfoLevel(2);
		}
		SetSprite();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
	}
	private void SetSprite()
	{
		switch (facingDir)
		{
		case FacingDirection.Up:
			projectileSpriteRenderer.sprite = sprites[0];
			projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
			projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
			break;
		case FacingDirection.Right:
			projectileSpriteRenderer.sprite = sprites[1];
			projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
			projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
			break;
		case FacingDirection.Down:
			projectileSpriteRenderer.sprite = sprites[2];
			projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
			projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
			break;
		case FacingDirection.Left:
			projectileSpriteRenderer.sprite = sprites[1];
			projectileSpriteRenderer.transform.localScale = Globals.ScaleVecFlipX;
			projectileSpriteRenderer.transform.localEulerAngles = Vector3.zero;
			projectileSpriteRenderer.transform.localPosition = new Vector3(0f, -0.75f, 0f);
			break;
		}
	}
	public override void ResetProjectile()
	{
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (!targetHit || targetEntity == null)
		{
			base.ResetProjectile();
			string audioID = "BallLightningEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, transform.position);
		}
	}
	private void OnTargetHit(Entity hitEntity)
	{
		if (!targetHit && !(hitEntity == null) && hitEntity is Enemy && !(hitEntity.hurtBoxTransform == null))
		{
			targetHit = true;
			targetEntity = hitEntity;
			wallCollider.enabled = false;
			attackBox.collider.enabled = false;
			hitStopwatchID = ChaosStopwatch.Begin(hitInterval, useInterval: true, hitInterval, maxHitCount);
			rigidbody2D.velocity = Vector2.zero;
			projectileSpriteRenderer.enabled = false;
			for (int i = 0; i < maxHitCount; i++)
			{
				PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(4, targetEntity.hurtBoxTransform.position);
				CreateShadow();
				curHitCount++;
			}
			base.ResetProjectile();
		}
	}
	private void CreateShadow()
	{
		currentShadow = Globals.ChaosInst<LightningShadow>(LightningShadow.Prefab, null, targetEntity.hurtBoxTransform.position + (Vector3)Globals.GetCirclePositionVector(maxHitCount, curHitCount) * 3f);
		currentShadow.Initialize(givenEmp: false, attackBox.atkInfo.skillCategory, attackBox.atkInfo.skillID, targetEntity.hurtBoxTransform, (targetEntity.hurtBoxTransform.position - (Vector3)Globals.GetCirclePositionVector(maxHitCount, curHitCount)).normalized, 0.1f * (float)curHitCount, givenUseBurst: false, givenReverseSpawnAnim: true);
	}
}

