using Chaos.AnimatorExtensions;
using UnityEngine;
public class LightningShadow : MonoBehaviour
{
	private static GameObject prefab;
	public Animator anim;
	public SpriteRenderer sprite;
	public Movement movement;
	public Attack attack;
	private string skillCat = string.Empty;
	private string skillID = string.Empty;
	private bool isEmpowered;
	private Transform targetTrans;
	private Vector2 targetVector;
	private float dashTime;
	private ChaosQuickStopwatch dashStopwatch = new ChaosQuickStopwatch();
	private bool dashStarted;
	private bool dashCompleted;
	private string facingDirStr = "Down";
	private int burstLevRadius;
	private Vector2 currentPosition;
	private Vector2 targetPosition;
	private bool useBurst = true;
	private bool reverseSpawnAnim;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/LightningShadow.prefab"));
	public void Initialize(bool givenEmp, string givenCat, string givenID, Transform givenTrans, Vector2 givenVector, float givenTime, bool givenUseBurst = true, bool givenReverseSpawnAnim = false)
	{
		isEmpowered = givenEmp;
		skillCat = givenCat;
		skillID = givenID;
		useBurst = givenUseBurst;
		reverseSpawnAnim = givenReverseSpawnAnim;
		targetTrans = givenTrans;
		targetVector = givenVector;
		dashTime = givenTime + 0.05f;
		burstLevRadius = ((!isEmpowered) ? 2 : 3);
		attack.SetAttackInfo(skillCat, skillID);
		attack.knockbackOverwriteVector = targetVector;
		sprite.material.SetFloat("_PaletteIndex", 6f);
		dashStopwatch.SetDelay(dashTime);
	}
	private void UpdateFacingDir()
	{
		if (targetTrans == null)
		{
			facingDirStr = "Down";
			return;
		}
		facingDirStr = Globals.GetPrimaryDirection((targetTrans.position - transform.position).normalized).ToString();
		if (facingDirStr == "Left")
		{
			transform.localScale = Globals.ScaleVecFlipX;
		}
	}
	private void Start()
	{
		anim.PlayDirectional(((!reverseSpawnAnim) ? "Spawn" : "SpawnReverse") + facingDirStr);
		dashStopwatch.IsRunning = true;
		PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect").Play(10f, transform.position + Vector3.up * 0.5f, LightningAuraEffect.EffectBGOverride, 0.12f);
		SoundManager.PlayWithDistAndSPR("BallLightningLoop", transform.position);
	}
	private void Update()
	{
		if (!dashStarted && !dashStopwatch.IsRunning)
		{
			dashStarted = true;
			UpdateFacingDir();
			anim.PlayDirectional("Attack" + facingDirStr);
			currentPosition = transform.position;
			targetPosition = targetVector * 0.5f + ((!(targetTrans == null) && !(Vector2.SqrMagnitude(transform.position - targetTrans.position) > 100f)) ? ((Vector2)targetTrans.position) : currentPosition);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, currentPosition, ParticleEffectOverrides.Radius0p75);
			SectionedTrailEmitter poolItem = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine");
			Vector2 startPos = currentPosition;
			Vector2 endPos = targetPosition;
			float delayTime = dashTime * 0.2f;
			poolItem.Emit(startPos, endPos, -1, emitEveryOther: false, -1f, snapToFit: true, -1f, delayTime);
			SectionedTrailEmitter poolItem2 = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningCompactTrail");
			endPos = currentPosition;
			startPos = targetPosition;
			delayTime = dashTime * 0.2f;
			poolItem2.Emit(endPos, startPos, -1, emitEveryOther: true, -1f, snapToFit: true, -1f, delayTime);
			SoundManager.PlayAudioWithDistance("TeleStrike", currentPosition);
		}
	}
	private void FixedUpdate()
	{
		if (dashStarted && !dashCompleted && movement.MoveToTarget(targetPosition, 0.5f))
		{
			dashCompleted = true;
			Reset();
		}
	}
	public void Reset()
	{
		currentPosition = transform.position;
		if (useBurst)
		{
			LightningBurst.CreateBurst(currentPosition, skillCat, skillID, burstLevRadius, burstLevRadius);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, currentPosition, ParticleEffectOverrides.RadiusOne);
		}
		SoundManager.PlayWithDistAndSPR("IonSpike", currentPosition);
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
	}
}

public class UsePhantomKnights : SkillState
{
	public new static string staticID = "UsePhantomKnights";

	private static string ultSkillID = "UsePhantomKnightsUlt";

	private List<int> skillLevelList = new List<int> { 1, 2, 3, 4, 5 };

	private PhantomKnight currentPK;

	private Vector2 spawnPosition;

	private Vector2 currentPosition;

	private StatData ultSkillData;

	private string calcSkillID;

	public override string OnEnterAnimStr => parent.GSlamAnimStr;

	public UsePhantomKnights(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		empoweredStat.SetInitialBaseValue(newBaseVal: true);
		SetAnimTimes(0.15f);
		ultSkillData = StatManager.GetSkillData(parent.skillCategory, ultSkillID);
	}

	public override void SetEmpowered(bool gs, BoolVarStatMod gm)
	{
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		currentPosition = parent.transform.position;
		if (isUltimate)
		{
			calcSkillID = ultSkillID;
			SyncUltSkillData();
			skillLevelList.Shuffle();
		}
		else
		{
			calcSkillID = skillID;
		}
		for (int i = 0; i < 5; i++)
		{
			spawnPosition = Globals.GetLinecastVector(currentPosition, currentPosition + Globals.GetCirclePositionVector(5, i) * 2.5f, ChaosCollisions.layerAllWallAndObst);
			currentPK = Globals.ChaosInst<PhantomKnight>(PhantomKnight.Prefab, parent.playerObjTrans, spawnPosition);
			currentPK.parentObj = parent.gameObject;
			currentPK.skillCategory = parent.skillCategory;
			currentPK.skillID = calcSkillID;
			currentPK.chargeAnimThreshold = 0.75f + (float)i * 0.15f;
			currentPK.chargeAnimStartTime = UnityEngine.Random.Range(0.5f, 0.75f);
			currentPK.skillLevel = ((!isUltimate) ? (-1) : skillLevelList[i]);
			currentPK.isUltimate = isUltimate;
			currentPK.playerSummonsList = parent.playerSummonsList;
			currentPK.targetRange = 10f;
